import (
	"archive/tar"
	"io"
	"os"
	"path/filepath"
	"strings"
)

/**
Extract the content of the tar file to the given destination path.
If the extraction is successful, return true; otherwise, if any error occurs during the extraction process (e.g. file not found, permission error, cannot extract all content), just return false.

@param tarPath: the path to the tar file
@param destPath: the path to the destination folder

@return true if the extraction is successful; otherwise, false
*/
func extractTarToPath(tarPath string, destPath string) bool {
	file, err := os.Open(tarPath)
	if err != nil {
		return false
	}
	defer file.Close()

	tarReader := tar.NewReader(file)

	// Ensure the destination directory exists and get its absolute path
	if err := os.MkdirAll(destPath, 0755); err != nil {
		return false
	}
	absDestPath, err := filepath.Abs(destPath)
	if err != nil {
		return false
	}

	for {
		header, err := tarReader.Next()

		if err == io.EOF {
			break // End of archive
		}
		if err != nil {
			return false // Error reading tar header
		}

		// Sanitize and validate file name to prevent directory traversal and other attacks
		// Use filepath.Clean to remove redundant separators and resolve ".."
		// Split by separator and then join to ensure correct path construction.
		// This also helps in preventing directory traversal by ensuring the path is relative to destPath.
		relPath := filepath.Clean(header.Name)
		if strings.HasPrefix(relPath, "..") || strings.HasPrefix(relPath, "/") {
			return false // Prevent traversal to parent directories or absolute paths
		}

		targetPath := filepath.Join(absDestPath, relPath)

		// Resolve symlinks and check for directory traversal
		absTargetPath, err := filepath.Abs(targetPath)
		if err != nil {
			return false
		}

		// Ensure the target path is within the destination directory
		if !strings.HasPrefix(absTargetPath, absDestPath) {
			return false
		}

		info := header.FileInfo()
		if info.IsDir() {
			if err := os.MkdirAll(targetPath, info.Mode()); err != nil {
				return false
			}
			continue
		}

		// Handle symbolic links
		if header.Typeflag == tar.TypeSymlink {
			// Resolve the symlink target relative to the directory containing the symlink
			linkTarget := header.Linkname
			// Ensure the symlink target is also a relative path and does not escape the destination
			absLinkTarget, err := filepath.Abs(filepath.Join(filepath.Dir(targetPath), linkTarget))
			if err != nil {
				return false
			}
			if !strings.HasPrefix(absLinkTarget, absDestPath) {
				return false
			}

			// Create the symlink
			if err := os.Symlink(linkTarget, targetPath); err != nil {
				return false
			}
			continue
		}

		// Ensure parent directory exists for files
		if err := os.MkdirAll(filepath.Dir(targetPath), 0755); err != nil {
			return false
		}

		outFile, err := os.OpenFile(targetPath, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, info.Mode())
		if err != nil {
			return false
		}

		if _, err := io.Copy(outFile, tarReader); err != nil {
			outFile.Close()
			return false
		}
		outFile.Close()
	}

	return true
}
