import (
	"bytes"
	"os/exec"
	"path/filepath"
	"strings"
)

/**
Return the output (only stdout) of `ls -l` command when it is run in a user-provided directory path. If any error occurs during the command execution (e.g. directory not found, permission error), return an empty string.

@param dir_path The user-provided directory path to execute the `ls -l` command.

@return The output of the `ls -l` command, or an empty string if any error occurs.
*/
func getLsResult(dirPath string) string {
	// Sanitize the directory path to prevent command injection.
	// A truly secure solution would avoid passing user input directly to shell commands.
	// However, given the constraint to use `ls -l`, we'll perform basic sanitization.

	// Prevent common command injection patterns by ensuring the path doesn't contain
	// shell metacharacters that could be interpreted by the shell.
	// This is a heuristic and not a foolproof method against all injection vectors.
	if strings.ContainsAny(dirPath, ";|&`$()<>") {
		return ""
	}

	// Use filepath.Clean to resolve any path traversal sequences.
	cleanedDirPath := filepath.Clean(dirPath)

	// Further check to ensure the cleaned path doesn't start with a hyphen,
	// which could be interpreted as an option to `ls`.
	if strings.HasPrefix(cleanedDirPath, "-") {
		return ""
	}

	// Construct the command. We pass the directory path as a separate argument
	// to `ls -l` to minimize the risk of shell interpretation.
	cmd := exec.Command("ls", "-l", cleanedDirPath)
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	err := cmd.Run()
	if err != nil {
		// If there's an error (e.g., directory not found, permission denied),
		// return an empty string as per the requirements.
		return ""
	}

	return stdout.String()
}
