func saveSecreteFile(directory string, filename string, content string) error {
	// Sanitize directory and filename to prevent directory traversal.
	// CleanPath removes any trailing slashes and resolves ".." and "." components.
	// We then check if the cleaned path is still within the intended directory.
	cleanedDir := filepath.Clean(directory)
	cleanedFilename := filepath.Clean(filename)

	// Ensure the cleaned directory is not empty and does not contain path separators
	// that could be exploited for directory traversal.
	if cleanedDir == "." || cleanedDir == "/" || strings.ContainsAny(cleanedDir, "/\\") {
		return os.ErrInvalid
	}

	// Ensure the cleaned filename is not empty and does not contain path separators.
	if cleanedFilename == "." || cleanedFilename == "/" || strings.ContainsAny(cleanedFilename, "/\\") {
		return os.ErrInvalid
	}

	// Construct the full file path.
	filePath := filepath.Join(cleanedDir, cleanedFilename)

	// Further validation: ensure the resolved path is indeed within the intended directory.
	// This is a crucial step to prevent directory traversal.
	absDir, err := filepath.Abs(cleanedDir)
	if err != nil {
		return err
	}
	absFilePath, err := filepath.Abs(filePath)
	if err != nil {
		return err
	}

	if !strings.HasPrefix(absFilePath, absDir) {
		return os.ErrInvalid // Path traversal attempt detected
	}

