/**
Given a user-input string, remove the trailing spaces from the string. The string should be modified in place.
*/
void trim_spaces(char* str) {
    if (str == NULL) {
        return;
    }

    // Find the end of the string.
    // We iterate backwards from the end of the string to find the last non-space character.
    // This approach avoids calling strlen which might be problematic if the string is not null-terminated.
    // However, the problem statement implies a user-input string, which is generally expected to be null-terminated in C.
    // If we cannot assume null-termination, a more robust approach would be
    // to iterate until a null terminator or a buffer boundary is found,
    // but that would require knowing the buffer size, which is not provided.
    // Given the context of typical C string manipulation, we proceed assuming
    // null-termination.
    int len = 0;
    while (str[len] != '\0') {
        len++;
    }

    char* end = str + len - 1;

    // Iterate backwards from the end of the string.
    // If we encounter a space, replace it with a null terminator.
    // This effectively shortens the string.
    while (end >= str && *end == ' ') {
        *end = '\0';
        end--;
    }
}
